#include "source/game.c"
#include <assert.h>
static void setup(Game*g,int raw){game_new(g,12345);game_choose_character(g,CHAR_REGENT);game_start_battle(g,NODE_FIGHT);g->hp=g->maxhp=50000;g->energy=99;g->regent.stars=99;g->enemy_count=2;for(int e=0;e<2;e++){g->enemies[e].hp=g->enemies[e].maxhp=50000;g->enemies[e].intent=0;g->enemies[e].intent_value=3;}g->hand_count=4;g->hand[0]=regent_stamp(g,raw);g->hand[1]=regent_stamp(g,R_VENERATE);g->hand[2]=regent_stamp(g,C_FINESSE);g->hand[3]=regent_stamp(g,R_DEFEND_REGENT);g->draw_count=4;g->draw[0]=regent_stamp(g,R_STRIKE_REGENT);g->draw[1]=regent_stamp(g,R_KINGLY_PUNCH);g->draw[2]=regent_stamp(g,R_KINGLY_KICK);g->draw[3]=regent_stamp(g,R_DEFEND_REGENT);g->discard_count=2;g->discard[0]=regent_stamp(g,R_STRIKE_REGENT);g->discard[1]=regent_stamp(g,R_DEFEND_REGENT);}
static void choices(Game*g){for(int steps=0;steps<100;steps++){if(g->screen==REGENT_CHOICE){int ix=-1;for(int i=0;i<game_regent_choice_count(g);i++)if(game_regent_choice_eligible(g,i)){ix=i;break;}assert(ix>=0);regent_choose(g,ix,0);}else if(g->screen==NINJA_CHOICE){int ix=-1;for(int i=0;i<g->hand_count;i++)if(game_ninja_choice_eligible(g,i)){ix=i;break;}assert(ix>=0);ninja_choose(g,ix,0);}else if(g->screen==CARD_CHOICE)settle_card_choice(g,0);else if(g->regent.task_count||g->ninja.task_count)game_update(g);else return;}assert(!"choice stuck");}
int main(void){Game g;int count=0;for(int id=REGENT_FIRST;id<EXTRA_LAST;id++)for(int up=0;up<2;up++){
 printf("CARD %d %s up%d\n",id,cards[id].name,up);fflush(stdout);setup(&g,id|(up?UPBIT:0));game_play_card(&g,0,0);choices(&g);if(!game_validate(&g)){printf("INVALID screen%d choice%d sel%d\n",g.screen,g.regent.choice_kind,g.selection);abort();}for(int t=0;t<3&&g.screen==COMBAT;t++){game_end_turn(&g);choices(&g);assert(game_validate(&g));}count++;}
 printf("PASS %d Regent and Colorless base/upgraded resolutions with three subsequent turns\n",count);return 0;}
